import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url));

export async function buildSupabaseBundle() {
  const directory = path.join(root, 'supabase/migrations');
  const names = (await readdir(directory)).filter(name => /^\d+_.+\.sql$/.test(name)).sort();
  if (!names.length) throw new Error('Nerasta Supabase migracijų.');
  const migrations = await Promise.all(names.map(async name => {
    const sql = await readFile(path.join(directory, name), 'utf8');
    // Keep one transaction for the whole fresh installation, including legacy access policies.
    return `-- ${name}\n${sql.replace(/^(?:begin|commit);\s*$/gim, '').trim()}`;
  }));
  return `-- Generated by npm run supabase:bundle. Do not edit this file.
-- ONLY for a new database without this application's tables.
-- Existing database: use migration list, repair (if needed), and db push.
-- After SQL Editor installation, register these versions in CLI migration history:
${names.map(name => `-- ${name.split('_')[0]}`).join('\n')}
begin;
do $$ begin
  if to_regclass('public.users') is not null
     or to_regclass('public.game_dates') is not null
     or to_regtype('public.user_role') is not null then
    raise exception 'APP_ALREADY_EXISTS: use versioned migrations for this database';
  end if;
end $$;

${migrations.join('\n\n')}

commit;
`;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const directory = path.join(root, 'supabase/generated');
  await mkdir(directory, { recursive: true });
  await writeFile(path.join(directory, 'bootstrap.sql'), await buildSupabaseBundle());
  console.log('Paruošta: supabase/generated/bootstrap.sql (tik naujai bazei).');
}
